# patterns: [regex on the whole French text, arabic template]; $1.. are the captured parts (translated again when they are known texts)
RULES = [
 [r'^(\d+) élèves$', 'COUNT:élèves:1'],
 [r'^Nouvelle classe \((\d+) élèves\)$', 'قسم جديد ($1 تلميذ)'],
 [r'^Rangée (\d+) · Table (\d+) · gauche$', 'الصف $1 · الطاولة $2 · يسار'],
 [r'^Rangée (\d+) · Table (\d+) · droite$', 'الصف $1 · الطاولة $2 · يمين'],
 [r'^(.+?)  \(R(\d+) · T(\d+)\)$', '$1  (ص$2 · ط$3)'],
 [r'^(\d+)/(\d+) placés · (\d+) sans place$', '$1/$2 جالسون · $3 بدون مقعد'],
 [r'^(\d+) fichier\(s\) supprimé\(s\)\.$', 'تم حذف $1 ملف(ات).'],
 [r'^(\d+) fichier\(s\) ajouté\(s\)\.$', 'تمت إضافة $1 ملف(ات).'],
 [r'^Supprimer la sélection \((\d+)\)$', 'حذف المحدد ($1)'],
 [r'^Supprimer (\d+) fichier\(s\) \? Cette action est définitive\.$', 'هل تريد حذف $1 ملف(ات)؟ هذا الإجراء نهائي.'],
 [r'^Supprimer la liste « (.*) » \?$', 'هل تريد حذف اللائحة «$1»؟'],
 [r'^Supprimer l’identifiant enregistré pour (.+) \?$', 'هل تريد حذف المعرّف المحفوظ لموقع $1؟'],
 [r'^Supprimer « (.+) » \? Vous perdrez ce générateur de codes : vérifiez que vous pouvez encore vous connecter au site autrement\.$', 'هل تريد حذف «$1»؟ ستفقد مولّد الرموز هذا: تأكد من أنك تستطيع تسجيل الدخول إلى الموقع بطريقة أخرى.'],
 [r'^(.+) : identifiant supprimé\.$', '$1 : تم حذف المعرّف.'],
 [r'^(.+) : (Enregistré\. Il sera rempli automatiquement\.)$', '$1 : $2'],
 [r'^(.+) ajouté$', 'تمت إضافة $1'],
 [r'^(\d+) compte\(s\) importé\(s\)(.*)$', 'تم استيراد $1 حساب(ات)$2'],
 [r', (\d+) déjà présent\(s\)', '، $1 موجود(ة) مسبقاً'],
 [r'^, (\d+) ignoré\(s\) \(pas basés sur le temps\)$', '، $1 متجاهَل (غير مبنية على الوقت)'],
 [r'^(\d+) classe\(s\)$', '$1 قسم(أقسام)'],
 [r'^(\d+) note\(s\)$', '$1 ملاحظة(ات)'],
 [r'^(\d+) fichier\(s\)$', '$1 ملف(ات)'],
 [r'^(\d+) identifiant\(s\) gardés pour plus tard$', '$1 معرّف(ات) محفوظة لوقت لاحق'],
 [r'^(\d+) compte\(s\) Authenticator gardés pour plus tard$', '$1 حساب(ات) Authenticator محفوظة لوقت لاحق'],
 [r'^Sauvegarde restaurée : (.+)\.$', 'تمت استعادة النسخة الاحتياطية : $1.'],
 [r'^Les cours commencent le (.+)\.$', 'تبدأ الدراسة يوم $1.'],
 [r'^Du (.+)\nau (.+)$', 'من $1\nإلى $2'],
 [r'^Dans (\d+) jours$', 'بعد $1 أيام'],
 [r'^Version (.+)$', 'الإصدار $1'],
 [r'^Une mise à jour est disponible \(version (.+)\) : téléchargement…$', 'يتوفر تحديث (الإصدار $1): جارٍ التنزيل…'],
 [r'^Téléchargement de la mise à jour : (\d+) %$', 'تنزيل التحديث: $1 %'],
 [r'^Aucun identifiant n’est enregistré pour (.+), ou cette page n’appartient pas au site\.$', 'لا يوجد معرّف محفوظ لموقع $1، أو أن هذه الصفحة لا تنتمي إلى الموقع.'],
 [r'^(.+) \(cliquez pour ouvrir\)$', '$1 (انقر للفتح)'],
 [r'^Période : (\d+)$', 'الفترة : $1'],
 [r'^Unité (\d+) :$', 'الوحدة $1 :'], [r'^Séance (\d+) :$', 'الحصة $1 :'],
 [r'^Unité (\d+) · Séance (\d+) — (.+)$', 'الوحدة $1 · الحصة $2 — $3'],
 [r'^(Lundi|Mardi|Mercredi|Jeudi|Vendredi|Samedi), (.+)$', '$1، $2'],
]

for fr, ar in [('Fichier enregistré', 'تم حفظ الملف'), ('Fiche enregistrée', 'تم حفظ البطاقة'), ('Feuille de notes enregistrée', 'تم حفظ ورقة النقط'),
               ('Plan enregistré', 'تم حفظ المخطط'), ('Emploi du temps enregistré', 'تم حفظ استعمال الزمن'), ('Sauvegarde enregistrée', 'تم حفظ النسخة الاحتياطية')]:
    RULES.append([r'^' + fr + r' : (.+)$', ar + ' : \u200E$1'])
